// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX4();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 0, address(this).balance == 0 ? 1 ether : 1 ether);
        vm.assume(data.length > 0);
        vm.assume(data.length <= 64);

        vm.deal(address(this), amount);
        c.Command{value: amount}(address(rec), data);

        // General rule: whatever calldata the owner asks c to forward must arrive
        // at the counterparty verbatim; its length is observable there.
        assertTrue(rec.dataLen() == data.length);
    }
}

contract Recorder {
    uint256 public dataLen;
    bytes public lastData;

    fallback() external payable {
        lastData = msg.data;
        dataLen = msg.data.length;
    }

    receive() external payable {}
}
